{
  "spells": [
    {
      "id": "spell_space_01",
      "theory": "界尺术把魔力压入两点之间的空气中，使其形成一条极淡的度量弦。弦只对可见点有效，墙壁、帷幕和门板都会截断它，因此不能借它探知隔间内部。河谷乡约用它校验田界，商队用它比对货箱长度，但弦本身没有标记，全凭施术者读取。",
      "casting": "右手拇指与食指捏合，在起点上方划一道短横，再朝终点缓缓拉开，同时低声念出目标点。",
      "failure": "弦会在中途弯折或提前消散，施术者读到的数字可能比实际短。若施术时手抖，弦会分裂成两段，让人误以为存在两个终点。",
      "counters": [
        "在两点之间举起不透明板，弦会被截断而无法读取。",
        "移动起点或终点的标记物，已形成的弦会失去参照。"
      ],
      "socialConsequences": "河谷农户乐于请人复测地界，免得秋收后争执。城市里，木匠和布商用它核对定制尺寸，但若借此窥探邻铺货架，同业会要求赔偿。港务记录员用测量结果核对提单，货主若发现数字被改动，可向港务申诉。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把三步读成两步，需反复校准起点。",
        "熟练后能在十步内保持弦线笔直，误差缩至一掌。",
        "精熟者可在嘈杂市场里稳定读数，不受旁人走动干扰。",
        "极精熟者能一次划定多个短距，但每段仍受可见范围限制。"
      ]
    },
    {
      "id": "spell_space_02",
      "theory": "袋序术让自有袋内的物品按取用顺序浮到袋口附近，魔力沿袋布内层形成细小滑轨，使物件滑移而不改变袋子的容量。它只作用于施术者本人所有的袋具，对他人背包或货箱无效。滑轨依赖袋布完整，破洞会让物件卡在夹层。",
      "casting": "左手按住袋底，右手食指沿袋口内缘画一圈，再轻拍袋身三下，同时默想需要取出的物品。",
      "failure": "袋内物件可能只浮起一半又落回，或几件小物同时挤向袋口，反而更难分辨。若袋布有裂口，物件会卡住，硬扯可能扯破袋角。",
      "counters": [
        "把袋口扎紧并压住袋底，滑轨无法形成。",
        "往袋内塞入粗糙麻布，物件会被纤维缠住而无法滑移。"
      ],
      "socialConsequences": "赶集的摊贩喜欢用它快速找零，但若在他人摊前反复掏袋，会被怀疑藏匿商品。城市行会允许成员在自有工具袋上使用，却禁止对公会货箱施术。港口搬运工用它整理随身小袋，港务提醒不得借此翻动待检货包。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把两件相似小物同时送到袋口，需要停下分拣。",
        "熟练后能按默想顺序逐件取出，减少翻找时间。",
        "精熟者可在行走中稳定取物，但袋内仍不能多装。",
        "极精熟者能隔着一层薄布感知目标位置，仍须袋布完整。"
      ]
    },
    {
      "id": "spell_space_03",
      "theory": "锚纹辨识让魔力流过可见的传送锚点纹路，根据纹路回阻判断其是否损坏。它只能读取锚点表面的魔纹状态，不能启动锚点，也不能绕过许可直接使用。河谷的旧驿柱、城市公会的门廊刻纹、港口的货栈标记都可以被读取。",
      "casting": "双指并拢，从锚纹外圈向内缓慢划过，在中心处停顿一息，感受魔力是否顺畅回流。",
      "failure": "若锚纹已损坏，魔力会在断口处散开，施术者指尖发麻，却读不出损坏位置。若锚纹被尘土覆盖，可能误判为完好，实际使用时会失效。",
      "counters": [
        "在锚纹表面覆盖厚泥或油布，魔力无法流入纹路。",
        "用另一道同频魔纹干扰外圈，可让读取结果混乱。"
      ],
      "socialConsequences": "河谷驿站看守会请过路法师检查旧锚柱，但不会因此放行。城市公会要求成员报告损坏锚点，擅自修补可能被视作越权。港口货栈依赖辨识结果决定是否启用备用锚点，若有人谎报损坏以拖延装船，港务会追查责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把表面污渍当成裂痕，需要反复擦拭确认。",
        "熟练后能分辨轻微磨损与真正断裂，减少误报。",
        "精熟者可在数息内读完常见锚纹，仍不能激活它。",
        "极精熟者能指出断裂大致方位，但修复仍须获准进行。"
      ]
    }
  ]
}
